/* Honest Cattle net-to-gate calculator — generated by build_bundle.js from calculator.html. Do not hand-edit. */
/*
 * Honest Cattle — net-to-gate market engine
 * --------------------------------------------------------------------------
 * Turns the weekly forecast price into the number that matters to a Montana
 * rancher: the net check at their own gate, after the price slide and after
 * trucking to Billings. Built for a CALF shipment, split by sex (steers and
 * heifers haul as separate loads because they weigh differently).
 *
 * Two informational year-over-year overlays sit BESIDE the net (they never
 * change it): a fuel/inflation overlay (2025 vs 2026 freight) and a calf-price
 * overlay (2025 vs 2026 price). Both are shown separately so the rancher sees
 * what this year's costs and prices did to the same calves.
 *
 * Pure functions, no deps. Browser (WP Snippet) + Node. Money USD, weight lb,
 * price $/cwt. Consumes market_snapshot.json — invents no market data.
 */

/* ----------------------------- slide engine ----------------------------- */
function slideDeductionCwt({ slideType, slideCwt = 0, baseWt, deliveryWt, capCwt = null }) {
  if (slideType === "none" || !slideCwt) return 0;
  const deltaCwt = (deliveryWt - baseWt) / 100;
  if (slideType === "one-way") return slideCwt * Math.max(0, deltaCwt);
  let deduction = slideCwt * deltaCwt; // two-way; negative when lighter
  if (slideType === "two-way-capped" && capCwt != null && deduction < 0) {
    deduction = Math.max(deduction, -capCwt);
  }
  return deduction;
}

/* ----------------------------- truckloads ------------------------------- */
/*
 * One sex per truckload. A standard cattle pot is taken to carry `payloadLb`
 * (default 63,000 lb of calves). Heavier calves => fewer head per load. The
 * last load of a sex may be partial, and you still hire the whole truck — so
 * trucks = ceil(head / headPerLoad) and freight is charged per truck-mile.
 */
function loadsForLot({ headcount, deliveryWt, payloadLb = 63000 }) {
  const headPerLoad = Math.max(1, Math.floor(payloadLb / deliveryWt));
  const trucks = Math.ceil(headcount / headPerLoad);
  const lastLoadHead = headcount - (trucks - 1) * headPerLoad;
  return { headPerLoad, trucks, lastLoadHead, partialLast: lastLoadHead < headPerLoad };
}

/* ----------------------- sale channel mechanics ------------------------- */
/*
 * Who pays the haul, and whether there's a pencil shrink, depends on how the
 * cattle are sold:
 *   regular-auction : SELLER hauls to the barn → freight is a SELLER cost (shown
 *                     separately, not in the check); cattle weighed at the barn,
 *                     so no pencil shrink (physical shrink already in the scale).
 *   video-auction   : BUYER hauls → freight priced into the bid (lowers the
 *                     offer, not a check line); pencil shrink applies.
 *   private-treaty  : BUYER hauls → same as video; pencil shrink applies.
 * Shrink defaults are typical/negotiated — override per deal.
 */
const SELLER_PAYS_FREIGHT = { "regular-auction": true, "video-auction": false, "private-treaty": false };
const DEFAULT_SHRINK_PCT = { "regular-auction": 0, "video-auction": 2.0, "private-treaty": 2.0 };

/* ------------------------- per-sex (lot) net ---------------------------- */
/*
 * Net for one sex. The NET CHECK is the sale proceeds only: bid (after slide) ×
 * PAY weight (after shrink), less auction commission. Trucking-when-buyer-pays
 * lives in the bid; the seller's own costs (trucking-when-seller-pays, brand
 * inspection, checkoff) come back in `sellerCosts`, shown SEPARATELY.
 */
function netToGateLot({
  headcount,
  deliveryWt,
  baseWt,
  baseCwt,            // 2026 Montana CASH $/cwt for this sex/band (see basis below)
  baseCwt2025 = null, // 2025 $/cwt for the price overlay (optional)
  cmeFuturesCwt = null, // CME feeder futures anchor (optional); with basisCwt derives baseCwt
  basisCwt = null,      // Montana cash basis = MT cash − CME futures (per band/sex)
  slideType = "none",
  slideCwt = 0,
  capCwt = null,
  saleChannel = "video-auction",
  shrinkPct = null,             // null => channel default
  milesToBillings = 0,
  ratePerLoadedMile = 0,        // 2026 rate
  ratePerLoadedMile2025 = null, // 2025 rate for the fuel/inflation overlay
  payloadLb = 63000,
  commissionPct = 0,            // auction commission, withheld from the check
  brandInspectionPerHead = 1.0, // MT DOL BE-10 (verified $1/head)
  checkoffPerHead = 1.0,        // national beef checkoff (verified $1/head; +$1 MT state if enacted)
}) {
  // Montana cash basis bridge: national futures + MT basis = MT cash price.
  if (baseCwt == null && cmeFuturesCwt != null && basisCwt != null) baseCwt = cmeFuturesCwt + basisCwt;
  const priceBridge = cmeFuturesCwt != null
    ? { cmeFuturesCwt, basisCwt: basisCwt != null ? basisCwt : baseCwt - cmeFuturesCwt, mtCashCwt: baseCwt }
    : null;

  const { headPerLoad, trucks, lastLoadHead, partialLast } = loadsForLot({ headcount, deliveryWt, payloadLb });
  const grossWtCwt = (headcount * deliveryWt) / 100;
  const shrink = shrinkPct != null ? shrinkPct : (DEFAULT_SHRINK_PCT[saleChannel] || 0);
  const payWtCwt = grossWtCwt * (1 - shrink / 100);          // you're paid on shrunk weight (video/private)

  const freightTotal = trucks * milesToBillings * ratePerLoadedMile;
  const sellerPaysFreight = SELLER_PAYS_FREIGHT[saleChannel] === true;

  // Buyer-paid freight is priced into the bid; seller-paid freight is a side cost.
  const buyerFreightCwt = !sellerPaysFreight && payWtCwt ? freightTotal / payWtCwt : 0;

  const slideCwtDed = slideDeductionCwt({ slideType, slideCwt, baseWt, deliveryWt, capCwt });
  const offeredCwt = baseCwt - buyerFreightCwt;             // the bid at the ranch
  const preCommissionCwt = offeredCwt - slideCwtDed;
  const commissionCwt = preCommissionCwt * (commissionPct / 100);

  const netCwt = preCommissionCwt - commissionCwt;
  const netCheck = netCwt * payWtCwt;                       // SALE PROCEEDS only

  // seller costs — paid by the seller, shown SEPARATELY, never in the net check
  const sellerFreight = sellerPaysFreight ? freightTotal : 0;
  const brandInspection = brandInspectionPerHead * headcount;
  const checkoff = checkoffPerHead * headcount;
  const sellerCostsLot = sellerFreight + brandInspection + checkoff; // vet cert is flat → added at shipment level

  // overlay counterfactuals (shown separately; never feed the net)
  const buyerFreight2025 = ratePerLoadedMile2025 != null ? trucks * milesToBillings * ratePerLoadedMile2025 : null;
  const opCostYoY = buyerFreight2025 != null ? freightTotal - buyerFreight2025 : null; // + = 2026 freight cut the bid more
  const priceYoY = baseCwt2025 != null ? (baseCwt - baseCwt2025) * payWtCwt : null;    // + = 2026 priced higher

  return {
    sexHeadcount: headcount, deliveryWt, headPerLoad, trucks, lastLoadHead, partialLast,
    saleChannel, shrinkPct: shrink, grossWtCwt, payWtCwt,
    baseCwt, priceBridge,
    // price formation: Billings market − buyer freight − slide = your bid
    price: { billingsCwt: baseCwt, buyerFreightCwt, slideCwt: slideCwtDed, offeredCwt, netCwt },
    buyerFreightCwt, offeredCwt, slideCwt: slideCwtDed, commissionCwt, freightTotal,
    netCwt, totalWtCwt: payWtCwt, netCheck,
    sellerCosts: { freight: sellerFreight, brandInspection, checkoff, total: sellerCostsLot },
    overlays: { opCostYoY, priceYoY, buyerFreight2025 },
    note: "Net check = sale proceeds on shrunk weight. Buyer-paid freight is in the bid; seller's freight/vet/brand/checkoff are shown separately, not in the check.",
  };
}

/* ----------------------- Montana cash basis ----------------------------- */
/*
 * Basis = local Montana cash price − CME futures, same class & week. Sourced
 * straight from the HCMI weekly pull (hcmi_index.py: GF futures, MT cash). It
 * is NOT an extra deduction — it's the bridge that explains the MT cash price:
 *   MT cash = CME futures + basis.
 * Surfaced for transparency ("the national number, brought home to Montana").
 */
function mtCashBasis({ mtCashCwt, cmeFuturesCwt }) {
  return mtCashCwt - cmeFuturesCwt;
}

/* ------------------- cull cows (HCMI boner component) -------------------- */
/*
 * The cull side of the same gate. Priced off the HCMI Boner cash $/cwt (the
 * MT_boner component), not the calf forecast. No weight slide (auction sale,
 * not a forward weight contract). Same truck + freight + YoY-overlay model.
 * Thin wrapper over netToGateLot with slide disabled.
 */
function cullNetToGate({
  headcount, weight, hcmiBonerCwt, hcmiBonerCwt2025 = null,
  saleChannel = "regular-auction",  // cull cows usually go through the barn
  shrinkPct = null,
  milesToBillings = 0, ratePerLoadedMile = 0, ratePerLoadedMile2025 = null,
  payloadLb = 63000, commissionPct = 0,
  brandInspectionPerHead = 1.0, checkoffPerHead = 1.0,
}) {
  return netToGateLot({
    headcount, deliveryWt: weight, baseWt: weight, slideType: "none",
    baseCwt: hcmiBonerCwt, baseCwt2025: hcmiBonerCwt2025,
    saleChannel, shrinkPct, milesToBillings, ratePerLoadedMile, ratePerLoadedMile2025,
    payloadLb, commissionPct, brandInspectionPerHead, checkoffPerHead,
  });
}

/* --------------------------- whole shipment ----------------------------- */
/*
 * Aggregate a steers lot + a heifers lot. `sexes` is keyed steers/heifers; omit
 * either if not shipping it. Shared fields (miles, rates, payload, commission)
 * are passed once and merged into each lot. Returns per-sex detail, the rolled
 * net, total trucks, and the two YoY overlays summed and shown SEPARATELY.
 */
function netToGateShipment({
  sexes,                      // { steers:{headcount,deliveryWt,baseWt,baseCwt,baseCwt2025,slide...}, heifers:{...} }
  saleChannel = "video-auction",
  shrinkPct = null,
  milesToBillings = 0,
  ratePerLoadedMile = 0,
  ratePerLoadedMile2025 = null,
  payloadLb = 63000,
  commissionPct = 0,
  brandInspectionPerHead = 1.0,
  checkoffPerHead = 1.0,
  vetCertFee = 25.0,          // flat, per shipment (one health certificate)
}) {
  const shared = { saleChannel, shrinkPct, milesToBillings, ratePerLoadedMile, ratePerLoadedMile2025, payloadLb, commissionPct, brandInspectionPerHead, checkoffPerHead };
  const lots = {};
  for (const sex of ["steers", "heifers"]) {
    if (sexes[sex] && sexes[sex].headcount > 0) lots[sex] = netToGateLot({ ...shared, ...sexes[sex] });
  }

  const sum = (f) => Object.values(lots).reduce((a, l) => a + (f(l) || 0), 0);
  const totalTrucks = sum((l) => l.trucks);
  const netCheck = sum((l) => l.netCheck);
  const totalHead = sum((l) => l.sexHeadcount);

  const opCostYoY = ratePerLoadedMile2025 != null ? sum((l) => l.overlays.opCostYoY) : null;
  const anyPriceYoY = Object.values(lots).some((l) => l.overlays.priceYoY != null);
  const priceYoY = sum((l) => (l.overlays.priceYoY != null ? l.overlays.priceYoY : 0));

  // seller costs — paid by the seller, shown SEPARATELY, never in the net check
  const sellerFreight = sum((l) => l.sellerCosts.freight);
  const brandInspection = sum((l) => l.sellerCosts.brandInspection);
  const checkoff = sum((l) => l.sellerCosts.checkoff);
  const sellerCostsTotal = sellerFreight + brandInspection + checkoff + vetCertFee;

  return {
    lots,
    totalHead,
    totalTrucks,
    saleChannel,
    netCheck,                                   // SALE PROCEEDS (slide + shrink + buyer freight in the bid)
    netPerHead: totalHead ? netCheck / totalHead : 0,
    sellerCosts: { freight: sellerFreight, brandInspection, checkoff, vetCert: vetCertFee, total: sellerCostsTotal },
    takeHome: netCheck - sellerCostsTotal,      // informational: check minus the seller's own out-of-pockets
    overlays: {
      // shown separately, hypothetical — never baked into netCheck
      fuelInflation: opCostYoY,                 // + dollars 2026 freight over 2025 (lowers the bid)
      calfPrice: anyPriceYoY ? priceYoY : null, // + dollars 2026 prices over 2025 (could be negative)
    },
  };
}

/* ------------------- rancher share of retail dollar --------------------- */
/*
 * Context ratio for the brand ("Recognizing Ranchers' Work"): the cow-calf
 * net check as a share of the RETAIL beef value the calf eventually becomes.
 * NOT a price input — shown beside the net.
 *
 *   carcassLb   = finishedWt × dressingPct
 *   retailLb    = carcassLb  × retailYieldPct
 *   retailValue = retailLb   × retailPricePerLb
 *   sharePct    = netPerHead / retailValue × 100
 *
 * Conversion constants are sourced standards (VERIFY), not invented:
 * dressing ~0.63, retail yield ~0.68, finished ~1400 lb. retailPricePerLb from
 * USDA ERS all-fresh retail (Apr 2026 ~ $9.64/lb).
 */
function rancherShareOfRetail({
  netPerHead,
  finishedWt = 1400,
  dressingPct = 0.63,
  retailYieldPct = 0.68,
  retailPricePerLb,
}) {
  const carcassLb = finishedWt * dressingPct;
  const retailLb = carcassLb * retailYieldPct;
  const retailValue = retailLb * retailPricePerLb;
  return {
    carcassLb, retailLb, retailValue,
    sharePct: retailValue ? (netPerHead / retailValue) * 100 : null,
  };
}

const HCMarket = { slideDeductionCwt, loadsForLot, netToGateLot, netToGateShipment, mtCashBasis, cullNetToGate, rancherShareOfRetail };
if (typeof module !== "undefined" && module.exports) module.exports = HCMarket;
if (typeof window !== "undefined") window.HCMarket = HCMarket;

