(function(){var s=document.createElement('style');s.textContent="\n  :root{\n    --cream:#f7f2e7; --cream2:#efe6d0; --paper:#fffdf7; --olive:#5c6b34; --olive-d:#3f4a23;\n    --ink:#2c2a22; --muted:#7c7560; --line:#ddd2b6; --accent:#8a7d4a; --warn:#9c5a2a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.45 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif}\n  .hccalc{max-width:1020px;margin:0 auto;padding:24px 18px 48px}\n  .hdr h1{font-family:Georgia,\"Times New Roman\",serif;font-size:26px;margin:0 0 2px;color:var(--olive-d)}\n  .hdr p{margin:0 0 18px;color:var(--muted)}\n  .grid{display:grid;grid-template-columns:340px 1fr;gap:20px}\n  @media(max-width:760px){.grid{grid-template-columns:1fr}}\n  .panel{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:16px}\n  .panel h3{margin:0 0 12px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}\n  label{display:block;font-size:12px;color:var(--muted);margin:10px 0 3px}\n  input,select{width:100%;padding:8px 9px;border:1px solid var(--line);border-radius:8px;background:#fff;font-size:15px;color:var(--ink)}\n  .two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .three{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}\n  fieldset{border:1px dashed var(--line);border-radius:10px;margin:14px 0 0;padding:6px 12px 12px}\n  legend{font-size:12px;color:var(--olive);padding:0 6px;text-transform:uppercase;letter-spacing:.05em}\n  details{margin-top:12px}\n  summary{cursor:pointer;color:var(--olive);font-size:13px}\n  .hero{background:var(--olive);color:#fff;border-radius:12px;padding:18px 20px;margin-bottom:14px}\n  .heroLabel{font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.85}\n  .heroNum{font-family:Georgia,serif;font-size:40px;font-weight:700;line-height:1.05;margin:4px 0}\n  .heroSub{opacity:.9;font-size:14px}\n  .card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin-bottom:12px}\n  .card h4{margin:0 0 8px;font-size:14px;color:var(--olive-d)}\n  table.bridge{width:100%;border-collapse:collapse;font-size:14px}\n  table.bridge td{padding:4px 0;border-bottom:1px solid #eee7d3}\n  table.bridge tr:last-child td{border-bottom:none}\n  td.r{text-align:right;font-variant-numeric:tabular-nums}\n  .muted{color:var(--muted);font-weight:400;font-size:12px}\n  .share{text-align:center}\n  .bigpct{font-family:Georgia,serif;font-size:38px;color:var(--olive);font-weight:700}\n  .ctx{margin-top:6px;text-align:center}\n  .foot{margin-top:22px;color:var(--muted);font-size:12px;text-align:center}\n  .badge{display:inline-block;background:var(--cream2);border:1px solid var(--line);border-radius:6px;padding:1px 7px;font-size:11px;color:var(--accent)}\n";document.head.appendChild(s);(document.getElementById('hc-calc-root')||document.body).innerHTML="<div class=\"hccalc\">\n  <div class=\"hdr\">\n    <h1>Your Montana market, read for you.</h1>\n    <p>Net-to-gate calculator <span class=\"badge\">prototype</span></p>\n  </div>\n\n  <div class=\"grid\">\n    <!-- INPUTS -->\n    <div class=\"panel\">\n      <h3>Your cattle &amp; sale</h3>\n      <label>County (haul distance to Billings)</label>\n      <select id=\"county\"></select>\n\n      <label>How are you selling?</label>\n      <select id=\"channel\">\n        <option value=\"video-auction\">Video auction (buyer hauls)</option>\n        <option value=\"private-treaty\">Private treaty (buyer hauls)</option>\n        <option value=\"regular-auction\">Regular auction (you haul to barn)</option>\n      </select>\n\n      <fieldset>\n        <legend>Steers</legend>\n        <div class=\"two\">\n          <div><label>Head</label><input id=\"stHead\" type=\"number\" min=\"0\" value=\"140\"></div>\n          <div><label>Weight (lb)</label><input id=\"stWt\" type=\"number\" min=\"0\" value=\"575\"></div>\n        </div>\n      </fieldset>\n      <fieldset>\n        <legend>Heifers</legend>\n        <div class=\"two\">\n          <div><label>Head</label><input id=\"hfHead\" type=\"number\" min=\"0\" value=\"90\"></div>\n          <div><label>Weight (lb)</label><input id=\"hfWt\" type=\"number\" min=\"0\" value=\"540\"></div>\n        </div>\n      </fieldset>\n\n      <label>Price slide</label>\n      <select id=\"slide\"></select>\n      <div id=\"customRow\" class=\"three\" style=\"display:none;margin-top:8px\">\n        <div><label>Type</label>\n          <select id=\"cType\">\n            <option value=\"one-way\">one-way</option>\n            <option value=\"two-way\">two-way</option>\n            <option value=\"two-way-capped\">two-way capped</option>\n          </select>\n        </div>\n        <div><label>$/cwt</label><input id=\"cSlide\" type=\"number\" step=\"0.5\" value=\"8\"></div>\n        <div><label>Base wt</label><input id=\"cBase\" type=\"number\" value=\"550\"></div>\n        <div style=\"grid-column:1/2\"><label>Cap $/cwt</label><input id=\"cCap\" type=\"number\" step=\"0.5\" value=\"\"></div>\n      </div>\n\n      <label>Pencil shrink (%) <span class=\"muted\">— auto by channel, editable</span></label>\n      <input id=\"shrink\" type=\"number\" step=\"0.5\" value=\"2\">\n\n      <fieldset>\n        <legend>Cull cows (optional)</legend>\n        <div class=\"two\">\n          <div><label>Head</label><input id=\"cullHead\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div><label>Weight (lb)</label><input id=\"cullWt\" type=\"number\" min=\"0\" value=\"1150\"></div>\n        </div>\n      </fieldset>\n\n      <details>\n        <summary>Advanced (rates &amp; fees)</summary>\n        <div class=\"two\">\n          <div><label>Freight $/loaded mi (2026)</label><input id=\"rate\" type=\"number\" step=\"0.25\"></div>\n          <div><label>Freight $/mi (2025)</label><input id=\"rate25\" type=\"number\" step=\"0.25\"></div>\n        </div>\n        <div class=\"three\">\n          <div><label>Commission %</label><input id=\"commission\" type=\"number\" step=\"0.5\" value=\"0\"></div>\n          <div><label>Brand $/hd</label><input id=\"brand\" type=\"number\" step=\"0.5\"></div>\n          <div><label>Checkoff $/hd</label><input id=\"checkoff\" type=\"number\" step=\"0.5\"></div>\n        </div>\n        <div class=\"two\">\n          <div><label>Vet cert (flat)</label><input id=\"vet\" type=\"number\" step=\"1\"></div>\n        </div>\n      </details>\n    </div>\n\n    <!-- RESULTS -->\n    <div class=\"panel\" id=\"out\"></div>\n  </div>\n\n  <div class=\"foot\">\n    Prototype — calf prices, basis, HCMI and retail are live; slide terms and the freight rate are still placeholder.<br>\n    Prepared by Dirk Adams with the assistance of AI.\n  </div>\n</div>";})();
(function(){
  var M=window.HCMarket, MILES=window.HC_MILES, SNAP=window.HC_SNAPSHOT;
  var $=function(id){return document.getElementById(id);};
  var money0=function(n){return '$'+Math.round(n).toLocaleString();};
  var moneyc=function(n){return '$'+n.toFixed(2);};
  var signed=function(n){return (n>=0?'+':'−')+'$'+Math.round(Math.abs(n)).toLocaleString();};

  // counties
  var csel=$('county');
  MILES.counties.slice().sort(function(a,b){return a.county.localeCompare(b.county);}).forEach(function(c){
    var o=document.createElement('option'); o.value=c.county;
    o.textContent=c.county+' · '+c.seat+' ('+(c.miles_to_billings==null?'?':c.miles_to_billings)+' mi)';
    csel.appendChild(o);
  });
  csel.value='Park';

  // slides
  var ssel=$('slide');
  var addOpt=function(v,t){var e=document.createElement('option');e.value=v;e.textContent=t;ssel.appendChild(e);};
  addOpt('none','No slide');
  (SNAP.slide_terms||[]).forEach(function(t,i){
    addOpt('term'+i, t.sale+' · '+t.type+' $'+t.slide_cwt+(t.cap_cwt?(' cap $'+t.cap_cwt):'')+(t.status==='pending'?' (pending)':''));
  });
  addOpt('custom','Custom…');

  // defaults from snapshot
  $('rate').value = (SNAP.freight&&SNAP.freight.rate_per_loaded_mile)!=null?SNAP.freight.rate_per_loaded_mile:4.0;
  $('rate25').value = (SNAP.freight&&SNAP.freight.rate_per_loaded_mile_2025)!=null?SNAP.freight.rate_per_loaded_mile_2025:'';
  $('brand').value = (SNAP.fees&&SNAP.fees.brand_inspection_per_head)!=null?SNAP.fees.brand_inspection_per_head:1;
  $('checkoff').value = (SNAP.fees&&SNAP.fees.checkoff_per_head)!=null?SNAP.fees.checkoff_per_head:1;
  $('vet').value = (SNAP.fees&&SNAP.fees.vet_cert_flat)!=null?SNAP.fees.vet_cert_flat:25;

  function num(id){var v=parseFloat($(id).value);return isFinite(v)?v:0;}
  function band(wt){var k=(wt<600)?'550-599':'600-649';return SNAP.bands[k]||SNAP.bands['550-599'];}
  function setShrinkForChannel(){var ch=$('channel').value;var sp=(SNAP.sale&&SNAP.sale.shrink_pct&&SNAP.sale.shrink_pct[ch]!=null)?SNAP.sale.shrink_pct[ch]:0;$('shrink').value=sp;}
  function toggleCustom(){$('customRow').style.display=($('slide').value==='custom')?'':'none';}
  function row2(a,b){return '<tr><td>'+a+'</td><td class="r">'+b+'</td></tr>';}

  function slideFor(wt){
    var v=$('slide').value;
    if(v==='none')return {slideType:'none',slideCwt:0,capCwt:null,baseWt:wt};
    if(v==='custom')return {slideType:$('cType').value,slideCwt:num('cSlide'),capCwt:(num('cCap')||null),baseWt:(num('cBase')||wt)};
    var t=SNAP.slide_terms[parseInt(v.replace('term',''),10)];
    return {slideType:t.type,slideCwt:t.slide_cwt,capCwt:(t.cap_cwt||null),baseWt:(t.base_wt||wt)};
  }

  function compute(){
    var row=MILES.counties.find(function(c){return c.county===csel.value;});
    var miles=row?row.miles_to_billings:0;
    var channel=$('channel').value, shrink=num('shrink'), rate=num('rate');
    var rate25=$('rate25').value!==''?num('rate25'):null;
    var payload=(SNAP.freight&&SNAP.freight.pot_payload_lb)||63000;
    var commission=num('commission'), brand=num('brand'), checkoff=num('checkoff'), vet=num('vet');

    var sexes={};
    var stHead=num('stHead'),stWt=num('stWt'),hfHead=num('hfHead'),hfWt=num('hfWt');
    // baseCwt is the forecast (headline). The calf-price YoY line is computed below from
    // actual-vs-actual cash, so baseCwt2025 is intentionally NOT passed to the engine.
    if(stHead>0&&stWt>0){var b=band(stWt),s=slideFor(stWt);sexes.steers={headcount:stHead,deliveryWt:stWt,baseWt:s.baseWt,baseCwt:b.steers_cwt,cmeFuturesCwt:b.cme_feeder_cwt,basisCwt:b.steers_basis,slideType:s.slideType,slideCwt:s.slideCwt,capCwt:s.capCwt};}
    if(hfHead>0&&hfWt>0){var b2=band(hfWt),s2=slideFor(hfWt);sexes.heifers={headcount:hfHead,deliveryWt:hfWt,baseWt:s2.baseWt,baseCwt:b2.heifers_cwt,cmeFuturesCwt:b2.cme_feeder_cwt,basisCwt:b2.heifers_basis,slideType:s2.slideType,slideCwt:s2.slideCwt,capCwt:s2.capCwt};}

    if(!Object.keys(sexes).length){$('out').innerHTML='<p class="muted">Enter steers and/or heifers to see your number.</p>';return;}

    var r=M.netToGateShipment({sexes:sexes,saleChannel:channel,shrinkPct:shrink,milesToBillings:miles,ratePerLoadedMile:rate,ratePerLoadedMile2025:rate25,payloadLb:payload,commissionPct:commission,brandInspectionPerHead:brand,checkoffPerHead:checkoff,vetCertFee:vet});

    var h='';
    h+='<div class="hero"><div class="heroLabel">Your calf check · '+channel.replace(/-/g,' ')+'</div><div class="heroNum">'+money0(r.netCheck)+'</div><div class="heroSub">'+money0(r.netPerHead)+'/head · '+r.totalHead+' head · '+r.totalTrucks+(r.totalTrucks===1?' truck':' trucks')+' to Billings ('+miles+' mi)</div></div>';

    ['steers','heifers'].forEach(function(k){
      var l=r.lots[k]; if(!l)return; var p=l.price;
      h+='<div class="card"><h4>'+k.charAt(0).toUpperCase()+k.slice(1)+' · '+l.sexHeadcount+' hd @ '+l.deliveryWt+' lb · '+l.trucks+(l.trucks===1?' truck':' trucks')+'</h4><table class="bridge">';
      h+=row2('Billings market',moneyc(p.billingsCwt)+'/cwt');
      if(p.buyerFreightCwt>0)h+=row2('− buyer freight to Billings','−'+moneyc(p.buyerFreightCwt)+'/cwt');
      if(p.slideCwt!==0)h+=row2((p.slideCwt>0?'− slide':'+ slide'),(p.slideCwt>0?'−':'+')+moneyc(Math.abs(p.slideCwt))+'/cwt');
      h+=row2('= your bid','<b>'+moneyc(p.netCwt)+'/cwt</b>');
      if(l.shrinkPct>0)h+=row2('paid on '+l.shrinkPct+'% shrunk weight',Math.round(l.payWtCwt*100).toLocaleString()+' lb');
      h+=row2('lot check',money0(l.netCheck));
      h+='</table></div>';
    });

    var sc=r.sellerCosts;
    h+='<div class="card"><h4>Seller costs <span class="muted">(you pay these — not taken out of the check)</span></h4><table class="bridge">';
    if(sc.freight>0)h+=row2('Trucking (you haul to barn)',money0(sc.freight));
    h+=row2('Brand inspection',money0(sc.brandInspection));
    h+=row2('Beef checkoff',money0(sc.checkoff));
    h+=row2('Vet certificate (flat)',money0(sc.vetCert));
    h+=row2('= seller costs','<b>'+money0(sc.total)+'</b>');
    h+=row2('Take-home after costs','<b>'+money0(r.takeHome)+'</b>');
    h+='</table></div>';

    // calf-price YoY — actual cash vs actual cash (AMS 1778); forecast stays the headline
    var calfYoY=0, hasCalfYoY=false;
    ['steers','heifers'].forEach(function(k){
      var l=r.lots[k]; if(!l)return;
      var bb=(k==='steers')?band(stWt):band(hfWt);
      var a26=bb[k+'_cwt_2026_actual'], a25=bb[k+'_cwt_2025'];
      if(a26!=null&&a25!=null){ calfYoY+=(a26-a25)*l.totalWtCwt; hasCalfYoY=true; }
    });
    if(hasCalfYoY||r.overlays.fuelInflation!=null){
      h+='<div class="card"><h4>2026 vs 2025 <span class="muted">(actual cash, shown separately)</span></h4><table class="bridge">';
      if(hasCalfYoY)h+=row2('Calf price vs last year',signed(calfYoY));
      if(r.overlays.fuelInflation!=null)h+=row2('Freight inflation on the bid',signed(-r.overlays.fuelInflation));
      h+='</table></div>';
    }

    var cullHead=num('cullHead'),cullWt=num('cullWt');
    if(cullHead>0&&cullWt>0&&SNAP.context&&SNAP.context.hcmi_boner_cwt){
      var c=M.cullNetToGate({headcount:cullHead,weight:cullWt,hcmiBonerCwt:SNAP.context.hcmi_boner_cwt,saleChannel:channel,milesToBillings:miles,ratePerLoadedMile:rate,payloadLb:payload,brandInspectionPerHead:brand,checkoffPerHead:checkoff});
      h+='<div class="card"><h4>Cull cows · '+cullHead+' hd @ '+cullWt+' lb <span class="muted">(off HCMI boner $'+SNAP.context.hcmi_boner_cwt+')</span></h4><table class="bridge">';
      h+=row2('Net','<b>'+moneyc(c.netCwt)+'/cwt</b>');
      h+=row2('Cull check',money0(c.netCheck)+' · '+c.trucks+(c.trucks===1?' truck':' trucks'));
      h+='</table></div>';
    }

    if(SNAP.retail&&SNAP.retail.all_fresh_retail_per_lb){
      var rep=r.lots.steers||r.lots.heifers; var nph=rep.netCheck/rep.sexHeadcount;
      var s=M.rancherShareOfRetail({netPerHead:nph,finishedWt:SNAP.retail.finished_wt_lb,dressingPct:SNAP.retail.dressing_pct,retailYieldPct:SNAP.retail.retail_yield_pct,retailPricePerLb:SNAP.retail.all_fresh_retail_per_lb});
      h+='<div class="card share"><h4>Your share of the retail beef dollar</h4><div class="bigpct">'+s.sharePct.toFixed(1)+'%</div><div class="muted">'+money0(nph)+'/head ÷ '+money0(s.retailValue)+' retail value (at $'+SNAP.retail.all_fresh_retail_per_lb+'/lb)</div></div>';
    }

    if(SNAP.context&&SNAP.context.hcmi_level){
      h+='<div class="muted ctx">HCMI '+SNAP.context.hcmi_level+' (2024=100) — market direction, not a price.</div>';
    }

    $('out').innerHTML=h;
  }

  var ids=['county','channel','stHead','stWt','hfHead','hfWt','slide','shrink','cullHead','cullWt','rate','rate25','commission','brand','checkoff','vet','cType','cSlide','cCap','cBase'];
  ids.forEach(function(id){var e=$(id);if(e)e.addEventListener('input',function(){if(id==='slide')toggleCustom();compute();});});
  $('channel').addEventListener('change',function(){setShrinkForChannel();compute();});

  setShrinkForChannel();
  toggleCustom();
  compute();
})();
